{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Execution Desk Data",
    "operation": "add",
    "url": "http://localhost:7806",
    "widgets_json": {
      "venue_exception_form": {
        "name": "Venue Exception Form",
        "description": "Record an execution venue exception.",
        "type": "table",
        "endpoint": "/venue-exception",
        "w": 20,
        "h": 10,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "exception",
            "type": "form",
            "label": "Exception",
            "endpoint": "/venue-exception-submit",
            "method": "POST",
            "inputParams": [
              {
                "paramName": "venue",
                "type": "text",
                "label": "Venue",
                "value": "ARCA"
              },
              {
                "paramName": "slippage_bps",
                "type": "number",
                "label": "Slippage bps",
                "value": 12,
                "min": 0
              },
              {
                "paramName": "record",
                "type": "button",
                "label": "Record"
              }
            ]
          },
          {
            "paramName": "venue_scope",
            "type": "text",
            "label": "Venue Scope",
            "value": "ARCA",
            "description": "Venue exception filter."
          }
        ]
      },
      "exception_metric": {
        "name": "Exceptions",
        "description": "Open execution exceptions.",
        "type": "metric",
        "endpoint": "/exception-count",
        "w": 5,
        "h": 4,
        "staleTime": 900000
      },
      "open_orders": {
        "name": "Open Orders",
        "description": "Live open orders blotter.",
        "type": "table",
        "endpoint": "/open-orders",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "order_id",
            "type": "text",
            "label": "Order"
          },
          {
            "paramName": "symbol",
            "type": "text",
            "label": "Symbol"
          },
          {
            "paramName": "qty",
            "type": "number",
            "label": "Qty",
            "formatter": "int"
          },
          {
            "paramName": "status",
            "type": "text",
            "label": "Status",
            "render": "titleCase"
          }
        ]
      }
    }
  }
}

